#include "stdlib/blas/ext/base/dcombinations.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/special/binomcoef.h"
#include <stdbool.h>
#include <stdint.h>


// MAIN //

/**
* Computes combinations of a specified length from double-precision floating-point strided array elements.
*
* @param N           number of indexed elements
* @param k           number of elements to combine
* @param replacement boolean indicating whether to allow duplication in combination
* @param X           input array
* @param strideX     stride length for X
* @param Out         output array
* @param LDO         stride length for the leading dimension of Out
*/
void API_SUFFIX(stdlib_strided_dcombinations)( const CBLAS_INT N, const CBLAS_INT k, const bool replacement, const double *X, const CBLAS_INT strideX, double *Out, const CBLAS_INT LDO ) {
	CBLAS_INT ox;
	CBLAS_INT oo;
	int64_t C;

	if ( replacement ) {
		C = stdlib_base_binomcoef( N + k - 1, k );
	} else {
		C = stdlib_base_binomcoef( N, k );
	}
	ox = stdlib_strided_stride2offset( N, strideX );
	oo = stdlib_strided_stride2offset( C, LDO );
	API_SUFFIX(stdlib_strided_dcombinations_ndarray)( N, k, replacement, X, strideX, ox, Out, LDO, 1, oo );
}

/**
* Computes combinations of a specified length from double-precision floating-point strided array elements using alternative indexing semantics.
*
* @param N           number of indexed elements
* @param k           number of elements to combine
* @param replacement boolean indicating whether to allow duplication in combination
* @param X           input array
* @param strideX     stride length for X
* @param offsetX     starting index for X
* @param Out         output array
* @param strideOut1  stride length for the first dimension of Out
* @param strideOut2  stride length for the second dimension of Out
* @param offsetOut   starting index for Out
*/
void API_SUFFIX(stdlib_strided_dcombinations_ndarray)( const CBLAS_INT N, const CBLAS_INT k, const bool replacement, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, double *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2, const CBLAS_INT offsetOut ) {
	CBLAS_INT indices[ k ];
	CBLAS_INT val;
	CBLAS_INT io;
	CBLAS_INT i;
	CBLAS_INT j;
	int64_t C;
	int64_t c;

	if ( N <= 0 || k <= 0 ) {
		return;
	}
	if ( !replacement && k > N ) {
		return;
	}

	// Compute total number of combinations:
	if ( replacement ) {
		C = stdlib_base_binomcoef( N + k - 1, k );
	} else {
		C = stdlib_base_binomcoef( N, k );
	}

	// Initialize combination index array:
	if ( replacement ) {
		for ( i = 0; i < k; i++ ) {
			indices[ i ] = 0;
		}
	} else {
		for ( i = 0; i < k; i++ ) {
			indices[ i ] = i;
		}
	}
	io = offsetOut;
	for ( c = 0; c < C; c++ ) {
		// Write current combination to output:
		for ( j = 0; j < k; j++ ) {
			Out[ io + (j * strideOut2) ] = X[ offsetX + (indices[ j ] * strideX) ];
		}
		io += strideOut1;

		// Advance to next combination:
		if ( replacement ) {
			// Find rightmost index that can be incremented:
			j = k - 1;
			while ( j >= 0 && indices[ j ] == N - 1 ) {
				j -= 1;
			}
			if ( j >= 0 ) {
				val = indices[ j ] + 1;
				for ( i = j; i < k; i++ ) {
					indices[ i ] = val;
				}
			}
		} else {
			// Find rightmost index that can be incremented:
			j = k - 1;
			while ( j >= 0 && indices[ j ] == N - k + j ) {
				j -= 1;
			}
			if ( j >= 0 ) {
				indices[ j ] += 1;
				for ( i = j + 1; i < k; i++ ) {
					indices[ i ] = indices[ i - 1 ] + 1;
				}
			}
		}
	}
	return;
}
